algorithms.pseudocode:
function JACOBI(a, n):
    require n odd and n >= 1
    a <- a mod n
    result <- 1
    while a != 0:
        while a is even:
            a <- a / 2
            if n mod 8 in {3, 5}:
                result <- -result          # supplementary law for (2|n)
        swap(a, n)
        if a mod 4 = 3 and n mod 4 = 3:
            result <- -result              # quadratic reciprocity sign
        a <- a mod n
    if n = 1: return result                # gcd was 1
    else:     return 0                     # gcd > 1

function TAU_DIRECT(N):
    total <- 0
    for n = 0 to N-1:
        s <- JACOBI(n, N)
        if s != 0:
            total <- total + s * exp(2*pi*i*n/N)
    return total                            # cost O(N log N)

function TAU_CLOSED_FORM(N):
    require N odd and squarefree
    if N mod 4 = 1: return sqrt(N)
    else:           return i * sqrt(N)      # cost O(1)

function COMPARE(N):
    a <- TAU_DIRECT(N); b <- TAU_CLOSED_FORM(N)
    return (a, b, |a - b|)                  # empirically |a-b| ~ 1e-14
